function largestPalindrome(n) {
  if (n === 1) {
    return 9;
  }
  const limit = 10 ** n;
  for (let upper = limit - 1; upper >= limit / 10; upper--) {
    const gapSum = limit - upper;
    const lower = Number(String(upper).split('').reverse().join(''));
    const discriminant = gapSum * gapSum - 4 * lower;
    if (discriminant < 0) {
      continue;
    }
    const root = Math.round(Math.sqrt(discriminant));
    if (root * root === discriminant) {
      return ((upper % 1337) * (limit % 1337) + lower) % 1337;
    }
  }
  return -1;
}

