function largestPalindrome(n) {
  // Try every pair of n-digit factors, largest first, and stop once no remaining pair can beat the best palindrome.
  const high = 10 ** n - 1;
  const low = 10 ** (n - 1);
  // Products of two 8-digit numbers pass 2^53, so they are multiplied exactly as BigInt.
  const multiply = (a, b) => (n <= 7 ? a * b : BigInt(a) * BigInt(b));
  const isPalindrome = (value) => {
    const text = String(value);
    for (let i = 0, j = text.length - 1; i < j; i++, j--) if (text[i] !== text[j]) return false;
    return true;
  };
  let best = 0;
  for (let x = high; x >= low; x--) {
    if (multiply(x, x) <= best) break;
    for (let y = x; y >= low; y--) {
      const product = multiply(x, y);
      if (product <= best) break;
      if (isPalindrome(product)) best = product;
    }
  }
  return Number(BigInt(best) % 1337n);
}

